{"results": [{"id": "hp_doc_299f58b5cd41164df58ab668e6dd10bb75850adef66c4cd7e0548fe8c15a7410", "title": "2002 AFL Grand Final", "text": "The 2002 AFL Grand Final was an Australian rules football game contested between the Brisbane Lions and the Collingwood Football Club, held at the Melbourne Cricket Ground in Melbourne on 28 September 2002. It was the 106th annual Grand Final of the Australian Football League (formerly the Victorian Football League), staged to determine the premiers for the 2002 AFL season. The match, attended by 91,817 spectators, was won by Brisbane by a margin of 9 points, marking that club's second premiership victory in a row and second premiership overall.", "score": 28.2919}, {"id": "hp_doc_186a2ac98ba0eb0792127a5157ca5903f32c0370437bed2a0cfa89e9ea279d2d", "title": "2010 AFL Grand Final", "text": "The 2010 AFL Grand Final was a series of two Australian rules football matches between the Collingwood Football Club and the St Kilda Football Club. Together they are considered the 114th annual Grand Final of the Australian Football League (formerly the Victorian Football League), and were staged to determine the premiers for the 2010 AFL season. The premiership is usually decided by a single match; however, as the first Grand Final ended in a draw, a Grand Final replay was played the following week and was won by Collingwood.", "score": 24.0076}, {"id": "hp_doc_db08cc82f3d47885c8b96a533492299b61f84cf2a25b56fa65be6ca3f4f026b9", "title": "2007 AFL Grand Final", "text": "The 2007 AFL Grand Final was an Australian rules football game contested between the Geelong Football Club and the Port Adelaide Football Club, held at the Melbourne Cricket Ground in Melbourne on 29 September 2007. It was the 111th annual Grand Final of the Australian Football League (formerly the Victorian Football League), staged to determine the premiers for the 2007 AFL season. The match, attended by 97,302 spectators, was won by Geelong by a margin of 119 points, the biggest in VFL/AFL Grand Final history. The victory marked Geelong's seventh premiership win, and ended its 44-year premiership drought.", "score": 23.4701}], "remaining_searches": 2}
